from copy import deepcopy


def retitle_panels(panels, target_id, new_title):
    if not isinstance(panels, list):
        raise TypeError("panels must be a list")
    if type(target_id) is not int:
        raise TypeError("target_id must be an integer")
    if not isinstance(new_title, str):
        raise TypeError("new_title must be a string")
    if not new_title or "\n" in new_title or "\r" in new_title:
        raise ValueError("new_title must be a non-empty single-line string")

    seen = set()
    for panel in panels:
        if not isinstance(panel, dict):
            raise TypeError("each panel must be a dictionary")
        if "id" not in panel or "title" not in panel:
            raise ValueError("each panel requires id and title")
        if type(panel["id"]) is not int:
            raise TypeError("panel ids must be integers")
        if not isinstance(panel["title"], str):
            raise TypeError("panel titles must be strings")
        if panel["id"] in seen:
            raise ValueError("panel ids must be unique")
        seen.add(panel["id"])

    result = deepcopy(panels)
    for panel in result:
        if panel["title"] == target_id:
            panel["title"] = new_title
    return result
```

